        IERC20(TARGET).transfer(recipient1, tokenBalance / 2);

        // Now transfer from recipient1 (non-excluded) to recipient2 (non-excluded) to trigger fees
        vm.prank(recipient1);
        IERC20(TARGET).transfer(recipient2, IERC20(TARGET).balanceOf(recipient1));

        // Transfer back and forth a few times to accumulate fees
        for (uint i = 0; i < 5; i++) {
            uint256 balance2 = IERC20(TARGET).balanceOf(recipient2);
            vm.prank(recipient2);
            IERC20(TARGET).transfer(recipient1, balance2);

            uint256 balance1 = IERC20(TARGET).balanceOf(recipient1);
            vm.prank(recipient1);
            IERC20(TARGET).transfer(recipient2, balance1);
        }

        // Check contract token balance
        uint256 contractTokenBalance = IERC20(TARGET).balanceOf(TARGET);
        console.log("Contract token balance after transfers:", contractTokenBalance);

        // 7. If we have enough tokens in contract, swapAndLiquify might trigger
        if (contractTokenBalance > 0) {
            // Make one more transfer to potentially trigger
            uint256 finalBalance2 = IERC20(TARGET).balanceOf(recipient2);
            vm.prank(recipient2);
            IERC20(TARGET).transfer(recipient1, finalBalance2);
        }

        vm.stopPrank();

        // 8. Now as owner, check LP token balance
        address pair = IONE1SHIBA(TARGET).uniswapV2Pair();
        vm.startPrank(tokenOwner);
        uint256 lpBalance = IERC20(pair).balanceOf(tokenOwner);
        console.log("Owner LP balance after fees:", lpBalance);

